import {tool} from "../../tools/tools";
import {Button} from "antd";

function trigger(param) {
    console.log('param------------', param)
    const text = tool.getAttribute(param, ['columnInfo', 'text',],);
    /*
    columnInfo
:
{title: '状态', type: 'trigger', trigger: ƒ}
columnKey
:
"status_display"
columnsInfo
:
{task_name: {…}, status_display: {…}, progress: {…}, start_time: {…}, time_spent: {…}, …}
index
:
4
record
:
{id: 209, task_name: '1', parent_task: null, index: 185, status: 'created', …}
spacePrivatePath
:
(7) ['setting', 'programmer', 'menu__task_dir', 'sub', 'menu__task', 'table', 'spacePrivate__root']
spacePublic
:
{path: 'task/back_task/', columns: {…}, columnsCreate: {…}, columnsUpdate: {…}, disableDownload: true, …}
spacePublicPath
:
(6) ['setting', 'programmer', 'menu__task_dir', 'sub', 'menu__task', 'table']
value
:
"已创建"



    */


    let trigger = tool.getAttribute(param, ['columnInfo', 'trigger',], () => {
    });

    let value = param.value;
    if (value === undefined || value === null) {
        value = null;
    } else {
        value = value.toString();
    }
    if (!value) value = text;
    return <Button
        type={'link'}
        onClick={() => trigger(param)}
    >{value}</Button>;
}

export {trigger};

